o2.xApplication.CloudDocument.MyShareExplorer=new Class({Extends:o2.xApplication.CloudDocument.Explorer,initData:function(){this.srv.execute("queryMyShareByPage",{page:this.page,pageSize:this.pageSize},function(e){e.dataList.each(function(e){e.name=e.fileName}.bind(this)),this.dataList=e.dataList,this._initData()}.bind(this))},loadBread:function(){this.breadNode.empty();var e=new Element("div.root_share").inject(this.breadNode);new Element("a",{text:"我收到的"}).inject(e).addEvent("click",function(){this.app.loadShareToMe()}.bind(this));new Element("span.separator",{text:"|"}).inject(e),new Element("a",{text:"我发出的"}).inject(e).addEvent("click",function(){this.app.loadMyShare()}.bind(this)).addClass("active")}}),o2.xApplication.CloudDocument.MyShareExplorer.View=new Class({Extends:o2.xApplication.CloudDocument.Explorer.View}),o2.xApplication.CloudDocument.MyShareExplorer.Document=new Class({Extends:o2.xApplication.CloudDocument.Explorer.Document});